import{_ as r,l as o,o as t,c as i,v as e,p as s,x as n,d as h,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Kalman 时变对冲比","description":"","frontmatter":{"title":"Kalman 时变对冲比","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/kalman-hedge.md","filePath":"quant/kalman-hedge.md","lastUpdated":1789023840000}'),_={name:"quant/kalman-hedge.md"};function d(E,a,b,B,c,A){const l=o("Mermaid");return t(),i("div",null,[a[1]||(a[1]=e('<h1 id="kalman-时变对冲比" tabindex="-1">Kalman 时变对冲比 <a class="header-anchor" href="#kalman-时变对冲比" aria-label="Permalink to &quot;Kalman 时变对冲比&quot;">​</a></h1><div class="epigraph"><p>若对冲比是随机游走的隐状态，观测方程是一条带噪声的价差，Kalman 滤波在每一期给出对冲比的条件均值与方差；静态协整回归是该滤波在状态噪声为零时的退化。</p><footer>—— 线性滤波见 Kalman, Journal of Basic Engineering 1960；金融状态空间见 Harvey, Forecasting, Structural Time Series Models and the Kalman Filter, 1989；配对应用见 Elliott, Van Der Hoek and Malcolm, Quantitative Finance 2005</footer></div><p><a href="/quant/engle-granger">Engle–Granger</a> 的 \\(\\beta\\) 在全样本是常数。<a href="/quant/johansen">Johansen</a> 的 \\(\\beta\\) 在 VECM 里也是常数。指数权重、成分股、相对流动性一变，常数对冲比留下的残差会慢慢变成另一条 \\(I(1)\\)。把 \\(\\beta_t\\) 写成状态、把价格写成观测，Kalman 滤波给出时变对冲比及其不确定度。Elliott 等人把配对交易写成这种状态空间，残差再按均值回复交易。Alexander 从协整谈最优对冲，已经强调对冲比应随共同趋势的权重调整；滤波是把「随时间调」变成每期可计算的递归。本篇写状态方程怎么设、过程噪声与量测噪声如何打架，以及时变 \\(\\beta\\) 与平稳价差之间的紧张关系。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>观测方程常用</p> \\[y_t=\\alpha_t+\\beta_t x_t+\\varepsilon_t,\\qquad \\varepsilon_t\\sim N(0,R), \\]<p>状态例如</p> \\[\\beta_t=\\beta_{t-1}+\\eta_t,\\qquad \\eta_t\\sim N(0,Q), \\]<p>\\(\\alpha_t\\) 可以是常数、随机游走或被省略。\\(y,x\\) 多为对数价格。\\(Q=0\\) 则 \\(\\beta\\) 恒定，滤波退化为递推最小二乘的极限形式；\\(Q\\) 大则 \\(\\beta_t\\) 紧跟噪声，价差 \\(y_t-\\hat\\beta_t x_t\\) 被解释变量吃掉，几乎没有可交易的偏离。问题是在「对冲比允许慢变」与「价差仍要有均值回复」之间选一组 \\(Q,R\\)。</p><p>滚动 OLS 也给出时变 \\(\\beta\\)，但窗口内等权、窗口外突然切断，没有状态方差，也无法用似然选窗口。Kalman 把窗口换成 \\(Q/R\\)：信噪比决定有效记忆长度。这是同一偏误–方差前线上的另一参数化。</p><h3 id="与协整假设的冲突" tabindex="-1">与协整假设的冲突 <a class="header-anchor" href="#与协整假设的冲突" aria-label="Permalink to &quot;与协整假设的冲突&quot;">​</a></h3><p>严格协整要求 \\(\\beta\\) 常数（或至少在样本内不变）。\\(\\beta_t\\) 随机游走意味着长期关系本身在漂，残差的无条件分布一般不平稳。交易上仍可能在短窗内看起来像 <a href="/quant/ou-spread">OU</a>，因为滤波强制残差在量测噪声尺度上小。你交易的是滤波创新，不是一个已被 Johansen 承认的 \\(I(0)\\) 组合。这不是实现细节：检验协整再 Kalman，逻辑上是两套模型，不能用迹检验给滤波残差背书。</p><p><span class="marginnote">\\(\\hat\\beta_{t|t}\\) 是用到当期 \\(y_t\\) 的滤波。回测若用 \\(\\hat\\beta_{t|t}\\) 在 \\(t\\) 开仓，含同期信息。可交易的是预测 \\(\\hat\\beta_{t|t-1}\\)，再用 \\(t\\) 的价格算价差。平滑 \\(\\hat\\beta_{t|T}\\) 只能做事后分析，不能进模拟撮合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>设定。</strong> 把 \\(\\alpha_t,\\beta_t\\) 堆成状态向量，转移矩阵为单位阵（随机游走）或带弱回复的对角（均值回复状态，更接近「\\(\\beta\\) 在某值附近摆」）。量测矩阵是 \\((1,x_t)\\)，注意 \\(x_t\\) 是时变的，系统是线性但不是时不变的，滤波公式仍然适用。初值用形成期 OLS，初始状态方差取大，让滤波迅速忘记初值。</p><p><strong>超参数。</strong> \\(Q,R\\) 可用预测误差分解的极大似然（Harvey）。\\(R\\) 过小，滤波认为价格精确，把一切偏差塞进 \\(\\beta\\)，价差无信号。\\(Q\\) 过小，滤波像全样本回归，结构变了反应慢。可令 \\(Q=\\lambda R\\)，只估一个信噪比。非高斯新息下 Kalman 仍是线性最小均方，但似然误设；厚尾可用 \\(t\\) 量测或稳健更新。</p><p>Elliott、Van Der Hoek 与 Malcolm 同时让价差水平服从均值回复状态，对冲比另做状态，滤波输出交易信号与 \\(\\beta_t\\)。这比「先回归再对残差套 OU」更一致：残差定义与 \\(\\beta\\) 更新来自同一似然。代价是参数更多，识别更差。</p><h3 id="与滚动回归、dls-的比较" tabindex="-1">与滚动回归、DLS 的比较 <a class="header-anchor" href="#与滚动回归、dls-的比较" aria-label="Permalink to &quot;与滚动回归、DLS 的比较&quot;">​</a></h3><p>滚动 OLS：实现简单，标准误用窗口内公式，忽略窗口重叠。Kalman：每期 \\(O(1)\\) 更新（状态维数小时），给出 \\(\\mathrm{Var}(\\beta_t\\mid \\mathcal{F}_t)\\)，可用状态方差过大时停止交易——对冲比不确定时不应加大腿。动态 OLS 仍假定常数 \\(\\beta\\)，只修正内生偏误，不替代时变状态。</p><p>对冲绩效用跟踪误差 \\(y_t-\\hat\\beta_{t|t-1}x_t\\) 的波动、以及 \\(\\hat\\beta\\) 的换手。\\(Q\\) 大则跟踪误差小、换手大，成本吃掉名义上更好的对冲。应在成本后比较，而不是比较滤波残差方差。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Kalman 增益把预测误差按「状态不确定 vs 量测噪声」的比例写进 \\(\\beta\\)。价格里一次无法被当前 \\(\\beta\\) 解释的移动，若 \\(Q/R\\) 大，被当成 \\(\\beta\\) 变了；若 \\(Q/R\\) 小，被当成价差偏离，留给交易规则。同一笔缺口，两种超参数给出两种叙事：结构变了该调对冲，还是暂时偏离该开仓。这就是时变对冲比策略的核心识别问题，不能靠把 \\(Q\\) 调到样本内夏普最大来解决——那会系统性地把可交易偏离解释成 \\(\\beta\\) 变动，残差被榨干。</p><p>预测误差应近似白噪声。若误差仍有单位根，状态维数不够（缺了 \\(\\alpha\\) 的漂移、或缺了第二条腿）。若误差有 ARCH，量测方差应变，可用自适应 \\(R\\) 或先对收益做 GARCH 再对对数价格比滤波。</p><p><span class="marginnote">Alexander（1999）强调协整对冲相对最小方差对冲的对象不同：前者对齐共同随机趋势，后者最小化短期方差。Kalman 若把 \\(\\beta\\) 跟得太紧，行为上滑向滚动最小方差，长期趋势对不齐，遇到共同漂移时两边一起亏。</span></p><h3 id="多腿与约束" tabindex="-1">多腿与约束 <a class="header-anchor" href="#多腿与约束" aria-label="Permalink to &quot;多腿与约束&quot;">​</a></h3><p>三资产以上，状态是向量 \\(\\beta_t\\)，量测仍是一条组合价。不可识别：许多 \\(\\beta\\) 给出同样拟合。需约束（系数和为 0、对基准回归）或把系统写成多量测（多对价格）。Johansen 的空间约束可以当成状态的线性约束，在更新后投影回去。否则 Kalman 篮子会对冲比在等价类里乱走，换手无意义。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>价格间断、除息、拆股必须在观测方程里处理，否则 \\(\\beta_t\\) 会跳一次来吸收公司行为。停牌时量测缺失，滤波应只做预测步。杠杆与整数股使 \\(\\hat\\beta_{t|t-1}\\) 不能精确执行，量化误差进入 \\(R\\)。</p><p>不要用平滑状态画「当时的价差」再计算入场——那是全样本信息。不要在 \\(Q\\) 上做网格搜索优化交易期 PnL。不要把状态方差当 VaR：它是 \\(\\beta\\) 的滤波不确定，不是组合市场风险。</p><p>与静态协整的分工：若经济上 \\(\\beta\\) 该稳定（期现乘数、固定转换比率），Kalman 的 \\(Q\\) 应极小，或根本不用。若 \\(\\beta\\) 该变（行业权重、统计篮子），Kalman 或滚动回归是对象，协整检验只做形成期筛选。两者叠用时，<a href="/quant/half-life-bands">阈值</a> 必须建在预测残差上，半衰期也应用预测残差的 AR(1)，否则参数描述的是另一条序列。</p><p><span class="marginnote">Kalman（1960）给的是线性高斯递归；Harvey 把似然与超参数估计写进计量。配对论文的贡献是把 \\(\\beta_t\\) 与均值回复放进同一状态空间，而不是发明新的滤波公式。工程上写错预测/滤波时点，比写错转移矩阵更容易把回测做假。</span></p>',31)),(t(),s(m,null,{default:n(()=>[p(l,{id:"mermaid-87",class:"mermaid",graph:"flowchart%20TD%0A%20%20PX%5B%22%E4%BB%B7%E6%A0%BC%20y_t%2C%20x_t%22%5D%20--%3E%20MEAS%5B%22%E9%87%8F%E6%B5%8B%3A%20y%20%3D%20%CE%B1%20%2B%20%CE%B2%20x%20%2B%20%CE%B5%22%5D%0A%20%20MEAS%20--%3E%20KF%5B%22Kalman%20%E9%A2%84%E6%B5%8B%20%CE%B2_%7Bt%7Ct-1%7D%22%5D%0A%20%20KF%20--%3E%20SPR%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E4%BB%B7%E5%B7%AE%E5%88%9B%E6%96%B0%22%5D%0A%20%20SPR%20--%3E%20RULE%5B%22OU%20%E9%98%88%E5%80%BC%E5%BC%80%E5%B9%B3%22%5D%0A%20%20KF%20--%3E%20UPD%5B%22%E6%BB%A4%E6%B3%A2%E6%9B%B4%E6%96%B0%20%CE%B2_%7Bt%7Ct%7D%22%5D%0A%20%20Q%5B%22Q%3A%20%E7%8A%B6%E6%80%81%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20KF%0A%20%20R%5B%22R%3A%20%E9%87%8F%E6%B5%8B%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20KF%0A%20%20Q%20--%3E%20ID%5B%22%E8%AF%86%E5%88%AB%3A%20%E7%BB%93%E6%9E%84%E5%8F%98%20vs%20%E5%8F%AF%E4%BA%A4%E6%98%93%E5%81%8F%E7%A6%BB%22%5D%0A%20%20R%20--%3E%20ID%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>时变对冲比可写成随机游走（或弱回复）状态，Kalman 每期给出 \\(\\hat\\beta_{t|t-1}\\) 与不确定度。</li><li>可交易信号必须用预测步，不能用滤波平滑；否则回测含同期信息。</li><li>\\(Q/R\\) 决定偏离被解释成 \\(\\beta\\) 变动还是价差；\\(Q\\) 过大则无信号，过小则不适应结构变化。</li><li>严格协整与随机游走 \\(\\beta\\) 冲突；滤波残差平稳不能用 Johansen 的 \\(p\\) 值证明。</li><li>成本后的跟踪误差与 \\(\\beta\\) 换手才是对冲绩效；状态方差可作「不敢加杠杆」的闸门。</li><li>出处：Kalman, <em>Journal of Basic Engineering</em>, 1960；Harvey, 1989；Elliott, Van Der Hoek, Malcolm, <em>Quantitative Finance</em>, 2005；协整对冲对象见 Alexander, <em>Philosophical Transactions of the Royal Society</em>, 1999。</li></ul>',2))])}const q=r(_,[["render",d]]);export{f as __pageData,q as default};
